import { MakeLogicType, actions, kea, listeners, path, reducers, selectors } from 'kea'

import { lemonToast } from '@posthog/lemon-ui'

import { FOCUS_INVESTIGATIONS } from './mockData'
import { DemoInvestigation, FocusActedStatus } from './types'

/** How long the acted-on card stays up before focus mode moves to the next report. */
const AUTO_ADVANCE_MS = 320

function clampIndex(index: number): number {
    return Math.max(0, Math.min(FOCUS_INVESTIGATIONS.length - 1, index))
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface investigationsFocusLogicValues {
    actedStatuses: Record<string, FocusActedStatus>
    agentMenuOpen: boolean
    counter: string
    currentIndex: number
    currentReport: DemoInvestigation | null
    expanded: boolean
    helpOpen: boolean
    prModalOpen: boolean
    reports: DemoInvestigation[]
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface investigationsFocusLogicActions {
    acknowledge: () => {
        value: true
    }
    confirmPr: () => {
        value: true
    }
    dismiss: () => {
        value: true
    }
    jumpTo: (index: number) => {
        index: number
    }
    navigate: (delta: number) => {
        delta: number
    }
    runPrimaryAction: () => {
        value: true
    }
    sendToAgent: (agentName: string) => {
        agentName: string
    }
    setActedStatus: (
        id: string,
        status: FocusActedStatus
    ) => {
        id: string
        status: FocusActedStatus
    }
    setAgentMenuOpen: (open: boolean) => {
        open: boolean
    }
    setExpanded: (expanded: boolean) => {
        expanded: boolean
    }
    setHelpOpen: (open: boolean) => {
        open: boolean
    }
    setPrModalOpen: (open: boolean) => {
        open: boolean
    }
    toggleExpanded: () => {
        value: true
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface investigationsFocusLogicMeta {
    __keaTypeGenInternalSelectorTypes: {
        currentReport: (reports: DemoInvestigation[], currentIndex: number) => DemoInvestigation | null
        counter: (reports: DemoInvestigation[], currentIndex: number) => string
    }
}

export type investigationsFocusLogicType = MakeLogicType<
    investigationsFocusLogicValues,
    investigationsFocusLogicActions,
    Record<string, any>,
    investigationsFocusLogicMeta
>

/**
 * Triage state for the mock-data focus mode: one investigation at a time, with
 * the acted-on outcomes kept in memory for the session. Nothing is persisted.
 */
export const investigationsFocusLogic = kea<investigationsFocusLogicType>([
    path(['products', 'signals', 'frontend', 'investigations-demo', 'investigationsFocusLogic']),
    actions({
        navigate: (delta: number) => ({ delta }),
        jumpTo: (index: number) => ({ index }),
        toggleExpanded: true,
        setExpanded: (expanded: boolean) => ({ expanded }),
        acknowledge: true,
        dismiss: true,
        runPrimaryAction: true,
        confirmPr: true,
        sendToAgent: (agentName: string) => ({ agentName }),
        setActedStatus: (id: string, status: FocusActedStatus) => ({ id, status }),
        setAgentMenuOpen: (open: boolean) => ({ open }),
        setHelpOpen: (open: boolean) => ({ open }),
        setPrModalOpen: (open: boolean) => ({ open }),
    }),
    reducers({
        currentIndex: [
            0,
            {
                navigate: (state, { delta }) => clampIndex(state + delta),
                jumpTo: (_, { index }) => clampIndex(index),
            },
        ],
        expanded: [
            false,
            {
                toggleExpanded: (state) => !state,
                setExpanded: (_, { expanded }) => expanded,
            },
        ],
        actedStatuses: [
            {} as Record<string, FocusActedStatus>,
            {
                setActedStatus: (state, { id, status }) => ({ ...state, [id]: status }),
            },
        ],
        agentMenuOpen: [
            false,
            {
                setAgentMenuOpen: (_, { open }) => open,
                sendToAgent: () => false,
                runPrimaryAction: () => false,
                navigate: () => false,
                jumpTo: () => false,
            },
        ],
        helpOpen: [
            false,
            {
                setHelpOpen: (_, { open }) => open,
                toggleExpanded: () => false,
                runPrimaryAction: () => false,
                navigate: () => false,
                jumpTo: () => false,
            },
        ],
        prModalOpen: [
            false,
            {
                setPrModalOpen: (_, { open }) => open,
                confirmPr: () => false,
            },
        ],
    }),
    selectors({
        reports: [() => [], (): DemoInvestigation[] => FOCUS_INVESTIGATIONS],
        currentReport: [
            (s) => [s.reports, s.currentIndex],
            (reports: DemoInvestigation[], currentIndex: number): DemoInvestigation | null =>
                reports[currentIndex] ?? null,
        ],
        counter: [
            (s) => [s.reports, s.currentIndex],
            (reports: DemoInvestigation[], currentIndex: number): string => `${currentIndex + 1} / ${reports.length}`,
        ],
    }),
    listeners(({ actions, values, cache }) => {
        const advanceAfterActing = (): void => {
            cache.disposables.add(() => {
                const timer = window.setTimeout(() => actions.navigate(1), AUTO_ADVANCE_MS)
                return () => clearTimeout(timer)
            }, 'autoAdvance')
        }

        const startInProgress = (report: DemoInvestigation): void => {
            if (!report.focus) {
                return
            }
            actions.setActedStatus(report.id, 'In progress')
            lemonToast.success(report.focus.fixToast)
        }

        return {
            acknowledge: () => {
                const report = values.currentReport
                if (!report) {
                    return
                }
                actions.setActedStatus(report.id, 'Acknowledged')
                lemonToast.success('Acknowledged, logged to the investigation record')
                advanceAfterActing()
            },
            dismiss: () => {
                const report = values.currentReport
                if (!report) {
                    return
                }
                actions.setActedStatus(report.id, 'Dismissed')
                lemonToast.success('Dismissed, kept for audit')
                advanceAfterActing()
            },
            runPrimaryAction: () => {
                const report = values.currentReport
                if (!report?.focus) {
                    return
                }
                if (report.focus.actionLabel === 'Fix & monitor') {
                    actions.setPrModalOpen(true)
                    return
                }
                startInProgress(report)
            },
            confirmPr: () => {
                const report = values.currentReport
                if (!report) {
                    return
                }
                startInProgress(report)
            },
            sendToAgent: ({ agentName }) => {
                const report = values.currentReport
                if (!report) {
                    return
                }
                lemonToast.success(`Handed off to ${agentName}: ${report.id} attached with full context`)
            },
        }
    }),
])
